// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Soft Folded Smoke
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Atlas)
// @param float _Columns = 2 [1 .. 4]
// @param float _Rows = 2 [1 .. 4]
// @param float _CellScale = 0.9 [0.3 .. 1]
// @param float _CellPadding = 0.035 [0 .. 0.2]
// @param float _CellFade = 0.18 [0.01 .. 0.4]
// @param float _Seed = 321 [1 .. ~5000]
// @endgroup
// @group(Shape)
// @param float _Radius = 0.235 [0.05 .. 0.35]
// @param float _Lobes = 7 [3 .. 16]
// @param float _PuffSize = 0.235 [0.06 .. 0.3]
// @param float _Warp = 0.035 [0 .. 0.18]
// @param float _Density = 1.15 [0.2 .. 3]
// @param float _EdgeSoftness = 0.11 [0.03 .. 0.2]
// @param float _ContourFlow = 0.13 [0 .. 0.6]
// @param float _Dissipation = 0.045 [0 .. 0.4]
// @endgroup
// @group(Structure)
// @param float _DetailScale = 1.7 [1 .. 12]
// @param float _Fold = 0.8 [0 .. 1]
// @param float _Detail = 0.22 [0 .. 1]
// @param float _Relief = 1 [0 .. 1]
// @param bool _AlphaOnly = false
// @endgroup
float SmokeHash(float2 p){return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453);}
float SmokeNoise(float2 p,float seed){fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;return fnlGetNoise2D(s,p.x,p.y)*.5+.5;}
float SmokeFbm(float2 p,float seed){return .64*SmokeNoise(p,seed)+.25*SmokeNoise(p*2.03,seed+31)+.11*SmokeNoise(p*4.07,seed+89);}
float4 ApplyFX(float2 uv,float4 color){
 float2 count=max(1,round(float2(_Columns,_Rows))),local=LayerToLocal(uv);
 float2 cell=floor(local*count),cellUV=frac(local*count)-.5;
 float2 p=cellUV/max(_CellScale,.001);
 float seed=_Seed+dot(cell,float2(71,193));
 float2 warp=float2(SmokeNoise(p*3,seed+5),SmokeNoise(p*3,seed+43))-.5;
 float2 q=p+warp*_Warp*2;
 float2 fineWarp=float2(SmokeNoise(q*6,seed+17),SmokeNoise(q*6,seed+59))-.5;
 q+=fineWarp*_Warp*.24;
 float density=0;
 [loop]for(int k=0;k<16;k++){
  if(k>=round(_Lobes))break;
  float h=SmokeHash(float2(k+seed,19)),h2=SmokeHash(float2(k,seed+7));
  float angle=k*2.39996+h*.7;
  float2 center=float2(cos(angle),sin(angle))*_Radius*sqrt(h2);
  float radius=_PuffSize*lerp(.72,1.3,h);
  float2 d=(q-center)/radius;
  d.x*=lerp(.85,1.15,h2);
  density+=exp(-dot(d,d)*1.7)*lerp(.65,1,h);
 }
 float broad=SmokeFbm(q*_DetailScale+warp*.7,seed+73);
 float folded=SmokeNoise(q*_DetailScale+fineWarp*.15+warp*.65,seed+37);
 float ridge=exp(-pow((folded-.52)/.23,2));
 float fine=SmokeFbm(q*(_DetailScale*2.4),seed+193);
 density*=lerp(1,lerp(.5,1.25,broad),.7);
 density*=lerp(1,lerp(.7,1.2,fine),_Detail);
 float transport=1-smoothstep(.25,1.2,density);
 float2 shapeQ=q+warp*_ContourFlow*transport;
 float transportedDensity=0;
 [loop]for(int j=0;j<16;j++){
  if(j>=round(_Lobes))break;
  float h=SmokeHash(float2(j+seed,19)),h2=SmokeHash(float2(j,seed+7));
  float angle=j*2.39996+h*.7;
  float2 center=float2(cos(angle),sin(angle))*_Radius*sqrt(h2);
  float radius=_PuffSize*lerp(.72,1.3,h);
  float2 d=(shapeQ-center)/radius;
  d.x*=lerp(.85,1.15,h2);
  transportedDensity+=exp(-dot(d,d)*1.7)*lerp(.65,1,h);
 }
 transportedDensity*=lerp(1,lerp(.5,1.25,broad),.7);
 transportedDensity*=lerp(1,lerp(.7,1.2,fine),_Detail);
 float material=lerp(density,transportedDensity,transport);
 float foldDensity=smoothstep(.22,.72,broad+.12*ridge);
 material*=lerp(1,lerp(.35,1.2,foldDensity),transport*.65);
 float a=(1-exp(-material*_Density))*.86;
 a*=smoothstep(_Dissipation,_Dissipation+_EdgeSoftness*3,material);
 // Independent fades on each side; the central density and shading stay intact.
 float2 borderDistance=.5-abs(cellUV);
 float2 borderFade=smoothstep(_CellPadding,_CellPadding+max(_CellFade,.001),borderDistance);
 a*=borderFade.x*borderFade.y;
 float2 lp=q*_DetailScale+warp*.5;
 float lighting=SmokeNoise(lp+float2(-.12,.18),seed+37)-SmokeNoise(lp-float2(-.12,.18),seed+37);
 float shade=.3+.53*broad+_Fold*(.65*lighting+.23*ridge)+(fine-.5)*_Detail*.15;
 shade+=.08*saturate(.5+q.y-q.x);
 shade=lerp(1,saturate(shade),_Relief);
 float3 rgb=GammaToLinearSpace(shade.xxx);
 if(_AlphaOnly>.5){a*=shade;rgb=1;}
 return float4(rgb,saturate(a)*_Opacity);
}
